const softDeleteFacePerson = `-- name: SoftDeleteFacePerson :one
UPDATE face_persons
SET deleted_at = now(), updated_by = $1, updated_at = now()
WHERE tenant_id = $2 AND id = $3 AND deleted_at IS NULL
RETURNING id, tenant_id, display_name, frigate_name, notes, created_by, updated_by, created_at, updated_at, deleted_at, sync_revision
`

type SoftDeleteFacePersonParams struct {
	UpdatedBy *uuid.UUID
	TenantID  uuid.UUID
	ID        uuid.UUID
}

func (q *Queries) SoftDeleteFacePerson(ctx context.Context, arg SoftDeleteFacePersonParams) (FacePerson, error) {
	row := q.db.QueryRow(ctx, softDeleteFacePerson, arg.UpdatedBy, arg.TenantID, arg.ID)
	var i FacePerson
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.DisplayName,
		&i.FrigateName,
		&i.Notes,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.SyncRevision,
	)
	return i, err
}

const updateFacePerson = `-- name: UpdateFacePerson :one
UPDATE face_persons
SET display_name = $1, notes = $2, updated_by = $3, updated_at = now()
WHERE tenant_id = $4 AND id = $5 AND deleted_at IS NULL
RETURNING id, tenant_id, display_name, frigate_name, notes, created_by, updated_by, created_at, updated_at, deleted_at, sync_revision
`

type UpdateFacePersonParams struct {
	DisplayName string
	Notes       string
	UpdatedBy   *uuid.UUID
	TenantID    uuid.UUID
	ID          uuid.UUID
}

func (q *Queries) UpdateFacePerson(ctx context.Context, arg UpdateFacePersonParams) (FacePerson, error) {
	row := q.db.QueryRow(ctx, updateFacePerson,
		arg.DisplayName,
		arg.Notes,
		arg.UpdatedBy,
		arg.TenantID,
		arg.ID,
	)
	var i FacePerson
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.DisplayName,
		&i.FrigateName,
		&i.Notes,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.SyncRevision,
	)
	return i, err
}

const upsertFaceSuggestionDecision = `-- name: UpsertFaceSuggestionDecision :exec
INSERT INTO face_suggestion_decisions (tenant_id, sighting_lo, sighting_hi, decision, similarity, decided_by)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (tenant_id, sighting_lo, sighting_hi) DO UPDATE
SET decision = EXCLUDED.decision, similarity = EXCLUDED.similarity, decided_by = EXCLUDED.decided_by, decided_at = now()
`

type UpsertFaceSuggestionDecisionParams struct {
	TenantID   uuid.UUID
	SightingLo uuid.UUID
	SightingHi uuid.UUID
	Decision   string
	Similarity float32
	DecidedBy  *uuid.UUID
}

func (q *Queries) UpsertFaceSuggestionDecision(ctx context.Context, arg UpsertFaceSuggestionDecisionParams) error {
	_, err := q.db.Exec(ctx, upsertFaceSuggestionDecision,
		arg.TenantID,
		arg.SightingLo,
		arg.SightingHi,
		arg.Decision,
		arg.Similarity,
		arg.DecidedBy,
	)
	return err
}
